+
+test("threshold boundaries depend on the current state", () => {
+  for (const [value, inactive, active] of [
+    [1, false, false],
+    [2, false, false],
+    [3, false, true],
+    [5, true, true],
+    [6, true, true],
+  ]) {
+    assert.equal(core.nextState(false, value, 2, 5), inactive);
+    assert.equal(core.nextState(true, value, 2, 5), active);
+  }
+});
+
+test("trace carries state through the hysteresis band without mutating values", () => {
+  const values = Object.freeze([3, 5, 4, 2, 3, 6, 2]);
+  assert.deepEqual(api.traceStates(values, 2, 5), [false, true, true, false, false, true, false]);
+  assert.deepEqual(values, [3, 5, 4, 2, 3, 6, 2]);
+});
+
+test("trace respects an initially active state", () => {
+  assert.deepEqual(api.traceStates([3, 2, 4, 5, 3], 2, 5, true), [true, false, false, true, true]);
+  assert.deepEqual(api.traceStates([], 2, 5, true), []);
+});
